package com.smart.agent.routing;import com.smart.agent.security.AgentUserContext;import java.util.*;import org.springframework.stereotype.Component;@Component public class ProjectProgressDomainContributor implements BusinessDomainContributor{public static final String CODE="PROJECT_PROGRESS";public static boolean matches(String q){return q!=null&&(q.contains("施工进度")||q.contains("项目进度")||q.contains("完成进度"));}public BusinessDomainDescriptor descriptor(){return new BusinessDomainDescriptor(CODE,"施工进度",List.of("projectProgress.query","projectProgress.clarifyDate"),List.of(new DataScopeDescriptor("PROJECT_MENU","项目菜单及可见项目范围",List.of("MENU","PROJECT_MEMBER"))),"REALTIME",List.of("施工进度","项目进度","完成进度"));}public boolean availableTo(AgentUserContext c){return c!=null&&c.permissions().contains("menu:project");}}
